const TAU=Math.PI*2;
const at=(s,d,l=0)=>({x:s.start.x+s.forward.x*d+s.right.x*l,z:s.start.z+s.forward.z*d+s.right.z*l});
export function configureTrial(section,e,mode){
 if(e.adventureVersion!==1||section.index<=(e.legacyThrough??-1))return section;
 const c=section.chapter,kind=section.kind==='coins'?c===1?'bonus':c===3?'crystals':null:section.kind==='rocks'&&[1,3].includes(c)?'moving':section.kind==='plants'?[0,3].includes(c)?'boulders':[2,4].includes(c)?'thorns':null:section.kind==='steps'&&[1,4].includes(c)?'wind':null;
 if(!kind)return section;const hard=mode==='challenge',t=section.trial={id:section.id+':'+kind,kind,hard,phase:section.index*.37};
 if(kind==='boulders'){section.plants=[];const count=Math.min(hard||section.area>0?3:2,Math.max(2,Math.floor((section.length-10)/4.8)+1));t.lanes=Array.from({length:count},(_,i)=>({id:t.id+':'+i,s:5+(section.length-10)*i/(count-1),phase:i*(hard?1.1:1.45),period:hard?4.7:6.2,rollDuration:hard?2.0:2.5,r:.72}));t.shelters=t.lanes.flatMap(lane=>[-1,1].map(sign=>({s:lane.s-1.8,lateral:sign*1.9,...at(section,lane.s-1.8,sign*1.9),r:.65})));}
 if(kind==='wind'){section.platforms=[];t.period=hard?5.4:6.8;t.active=hard?2.2:2.1;t.warning=1.0;t.covers=Array.from({length:Math.max(2,Math.floor((section.length-5)/6))},(_,i)=>{const s=5+i*6,lateral=(i%2?1:-1)*1.7;return{id:t.id+':cover:'+i,s,lateral,...at(section,s,lateral),r:.65};});}
 if(kind==='thorns'){section.plants=[];t.rows=Array.from({length:Math.max(2,Math.floor((section.length-5)/5.2))},(_,i)=>({id:t.id+':row:'+i,s:5+i*5.2,phase:i*.35,period:hard?4.6:6.2,warning:1.25,gapWidth:2.6}));}
 if(kind==='moving')for(const[p,i]of section.platforms.map((p,i)=>[p,i])){p.fragile=false;if(i>0&&i<section.platforms.length-1)p.motion={ampL:hard?.55:.38,ampS:hard?.18:.10,period:(hard?6:7.6)+i*.25,phase:i*.7};} 
 if(kind==='crystals'){t.s=section.length*.53;t.hp=3;t.period=hard?4.5:5.5;t.openFor=hard?1.7:2.8;t.nodes=[-1.8,0,1.8].map(lateral=>({lateral,...at(section,t.s,lateral)}));}
 if(kind==='bonus'){section.platforms=[];for(let i=0;i<8;i++){const s=3+i*2.35,y=.18*Math.min(5,i+1);if(s>section.length-2.5)break;section.platforms.push({id:t.id+':ledge:'+i,s,lateral:1.35,...at(section,s,1.35),r:.90,y,bonus:true});}section.coins=section.coins.filter((_,i)=>i%2===0).map(coin=>({...coin,...at(section,coin.s,-1.15),lateral:-1.15}));section.platforms.filter(p=>p.y>=.54).forEach((p,i)=>section.coins.push({id:section.id+':coin:bonus:'+i,s:p.s,lateral:p.lateral,...at(section,p.s,p.lateral),y:p.y+.58,minFootY:p.y-.08}));}
 return section;
}
export function movingPose(section,p,time=0){if(!p.motion)return{x:p.x,z:p.z,y:p.y};const m=p.motion,cycle=TAU*time/m.period+m.phase,wave=Math.max(-1,Math.min(1,Math.sin(cycle)*1.14)),s=p.s+m.ampS*wave,l=p.lateral+m.ampL*wave;return{...at(section,s,l),y:p.y};}
export function coinPose(section,coin,time=0){const platform=section.trial?.kind==='moving'?section.platforms.find(p=>Math.abs(p.s-coin.s)<.01):null;if(!platform)return coin;const pose=movingPose(section,platform,time);return{...coin,x:pose.x,z:pose.z};}
export function boulderPose(section,lane,time=0){const phase=((time+lane.phase)%lane.period+lane.period)%lane.period,visible=phase<lane.rollDuration,warning=phase>lane.period-1.1,progress=Math.min(1,phase/lane.rollDuration),lateral=-4+8*progress;return{...at(section,lane.s,lateral),visible,warning,progress};}
export function gustState(section,time=0){const t=section.trial,phase=((time+t.phase)%t.period+t.period)%t.period,cycle=Math.floor((time+t.phase)/t.period);return{active:phase<t.active,warning:phase>t.period-t.warning,sign:cycle%2?1:-1};}
export function thornState(row,time=0){const clock=time+row.phase,cycle=Math.floor(clock/row.period),phase=((clock%row.period)+row.period)%row.period,gaps=[-1.2,0,1.2];return{gap:gaps[((cycle%3)+3)%3],nextGap:gaps[((cycle+1)%3+3)%3],warning:phase>row.period-row.warning};}
export function crystalState(section,time=0){const t=section.trial,phase=((time+t.phase)%t.period+t.period)%t.period;return{open:phase<t.openFor,warning:phase>t.period-.8};}
export function trialHint(section){return({boulders:'Watch the amber lanes · wait in the side alcoves',wind:'Gust coming? Shelter behind the stone covers',moving:'Ride the turquoise platforms · time your next jump',thorns:'Follow the green gaps · amber marks the next opening',crystals:'Strike the exposed crystals when their shells open',bonus:'Leaf route: safe · gold ledges: extra coins'}[section?.trial?.kind]||'');}
